describe('useI18n outside a provider', () => {
  it('answers with the context default rather than throwing', async () => {
    let ctx: ReturnType<typeof useI18n> | null = null;
    const Probe = () => { ctx = useI18n(); return <Text>{ctx.locale}</Text>; };
    let tree!: renderer.ReactTestRenderer;
    // no I18nProvider: a component rendered in isolation (a test, a storybook
    // entry, a screen mounted bare) must still be able to read the context
    act(() => { tree = renderer.create(<Probe />); });
    expect(LOCALES).toContain(ctx!.locale);
    expect(typeof ctx!.t('any.key')).toBe('string');
    // the default setLocale reports "no relaunch needed" and changes nothing
    await act(async () => { await expect(ctx!.setLocale(LOCALES[0]!)).resolves.toBe(false); });
    act(() => tree.unmount());
  });
});

describe('layout direction on the web build', () => {
  it('flips the document direction live, with no relaunch', async () => {
    const realOS = Platform.OS;
    const g = globalThis as { document?: { documentElement: { dir: string } } };
    const realDoc = g.document;
    g.document = { documentElement: { dir: 'ltr' } };
    Object.defineProperty(Platform, 'OS', { value: 'web', configurable: true });
    try {
      let ctx: ReturnType<typeof useI18n> | null = null;
      const Probe = () => { ctx = useI18n(); return <Text>{ctx.locale}</Text>; };
      let tree!: renderer.ReactTestRenderer;
      await act(async () => { tree = renderer.create(<I18nProvider><Probe /></I18nProvider>); });
      const rtl = RTL_LOCALES[0] ?? LOCALES[0]!;
      let needsRelaunch = true;
      await act(async () => { needsRelaunch = await ctx!.setLocale(rtl); });
      // the web build never needs a restart — it sets <html dir> and carries on
      expect(needsRelaunch).toBe(false);
      expect(['rtl', 'ltr']).toContain(g.document!.documentElement.dir);
      expect(ctx!.locale).toBe(rtl);
      await act(async () => tree.unmount());
    } finally {
      Object.defineProperty(Platform, 'OS', { value: realOS, configurable: true });
      g.document = realDoc;
    }
  });
});
